def icon(name: str, size: int = 64) -> str:
    """
    Возвращает SVG-иконку как inline HTML.
    Использование в Jinja2: {{ icon('shopping-cart') }}
    """
    svg = ICONS.get(name, "")
    if not svg:
        return f'<!-- icon "{name}" not found -->'
    if size != 64:
        svg = svg.replace('width="64"', f'width="{size}"')
        svg = svg.replace('height="64"', f'height="{size}"')
    return svg


def icon_list() -> list:
    """Возвращает список всех доступных имён иконок."""
    return sorted(ICONS.keys())
